function preload()
{
	  vertSource = loadStrings('https://openprocessing.org/sketch/1746095/files/default.vert');
		fragSource = loadStrings('https://openprocessing.org/sketch/1746095/files/waves.frag');
}

function setup() {
	pixelDensity(1);
	createCanvas(1024,1024,WEBGL);
	vertSource = resolveLygia(vertSource);
  fragSource = resolveLygia(fragSource);
	shdr = createShader(vertSource, fragSource);
}

function draw() {
	shader(shdr);

  shdr.setUniform('u_resolution', [width, height] );
  shdr.setUniform('u_mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  shdr.setUniform('u_time', millis() / 1000.0);

  rect(0,0, width, height);
}

// === Tab: waves.frag ===
#ifdef GL_ES
precision mediump float;
#endif

uniform sampler2D   u_tex0;
uniform vec2        u_tex0Resolution;

uniform vec2    u_resolution;
uniform float   u_time;

#include "lygia/space/ratio.glsl"
#include "lygia/math/rotate2d.glsl"
#include "lygia/math/const.glsl"
#include "lygia/draw/fill.glsl"
#include "lygia/draw/circle.glsl"
#include "lygia/sdf/lineSDF.glsl"
#include "lygia/sdf/circleSDF.glsl"
#include "lygia/generative/random.glsl"
#include "lygia/math/map.glsl"

#define S(a,b,c) smoothstep(a,b,c)

vec3 RED    = vec3(1.,0.,0.);
vec3 YELLOW = vec3(254., 179., 15.)/255.;
vec3 BLUE   = vec3(10., 164., 247.)/255.;
vec3 WHITE  = vec3(1.);
vec3 BLACK  = vec3(0.);

// select color from index 

vec3 generateColor(int inx)
{
   if (inx == 0)
   {
    return RED;
   }else if (inx == 1)
   {
    return YELLOW;
   }else if (inx == 2)
   {
    return BLUE;
   }else if (inx == 3)
   {
    return BLACK;
   }else
   {
    return BLUE;
   }
}

vec2 tile (vec2 _st, float _zoom) {
    _st *= _zoom;
    return fract(_st);
}

vec2 rotate2D (vec2 _st, float _angle) {
    _st -= 0.5;
    _st =  mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle)) * _st;
    _st += 0.5;
    return _st;
}


vec2 truchetPattern(in vec2 _st, in float _index){
    _index = fract(((_index-0.5)*2.0));
    if (_index > 0.75) {
        _st = vec2(1.0) - _st;
    } else if (_index > 0.5) {
        _st = vec2(1.0-_st.x,_st.y);
    } else if (_index > 0.25) {
        _st = 1.0-vec2(1.0-_st.x,_st.y);
    }
    return _st;
}

vec3 circularPattern(vec2 st,float rad,vec3 color,vec3 myColor)
{  
   float lw = 0.1;
   color += circle(st + 0.5,rad,lw)*myColor;
   color = mix(myColor,color,1.0 - circle(st - 0.5,rad,lw));
   return color;
}

void main(void) {

    vec3 color = BLACK;

    vec2 st = gl_FragCoord.xy/u_resolution.xy;

    st = ratio(st, u_resolution);

    st *= 4.;

    //color += 2.0*texture2D(u_tex0, st).rgb;

    float freq1 = 10.;
    float freq2 = 10.;

    float x = st.x;
    float y = st.y;

    st = vec2(x + cos(freq1*y + 0.5*u_time)*0.1,y + cos(freq2*x + 0.5*u_time)*0.1);

    vec2 ipos = floor(st);  // integer
    vec2 fpos = fract(st);  // fraction

    st = truchetPattern(fpos, random( ipos ));


    float  i=0.;
    vec3 temp;
    for(float r = 1.24;r > 0.2;r-=1.2/5.)
    {
      i = mod(i,6.);
      //i = random(r*i*1456234.)*2. + 4.;
      temp = generateColor(int(i));
      color += circularPattern(st,r,color,temp);
      i++;
    }

    if (fpos.x > 0.98 || fpos.y > 0.98) color += WHITE;

    gl_FragColor = vec4(color,1.0);

}


